content.text:
The evidence points to one root cause: a slow method in ts-route-service, with its latency carried up to the user-facing dashboard. I'm writing up the findings.

```json
{
  "root_causes": [
    {
      "service": "ts-route-service",
      "fault_kind": "application_method_slow",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT span_name, attr_span_kind, count(*) n, approx_quantile(duration,0.5)/1e6 p50_ms FROM abnormal_traces WHERE service_name='ts-route-service' AND span_name='RouteController.queryById' GROUP BY 1,2",
          "claim": "RouteController.queryById self-time jumps to about 1492 ms p50, versus about 1.2 ms in normal period."
        },
        {
          "kind": "trace",
          "sql": "SELECT p, span_name, n, p50_ms FROM (SELECT 'abn' p, span_name, count(*) n, approx_quantile(duration,0.5)/1e6 p50_ms FROM abnormal_traces WHERE service_name='ts-route-service' AND span_name LIKE 'SELECT%' GROUP BY 1,2 UNION ALL SELECT 'norm', span_name, count(*), approx_quantile(duration,0.5)/1e6 FROM normal_traces WHERE service_name='ts-route-service' AND span_name LIKE 'SELECT%' GROUP BY 1,2) t ORDER BY 2,1",
          "claim": "Route-service database SELECT spans stay around 0.1 to 0.5 ms, so the delay is not in DB calls."
        },
        {
          "kind": "trace",
          "sql": "SELECT span_name, attr_span_kind, count(*) n, approx_quantile(duration,0.5)/1e6 p50_ms FROM abnormal_traces WHERE service_name='ts-route-service' AND attr_span_kind='Server' GROUP BY 1,2 ORDER BY 1",
          "claim": "Route-service GET /routes/{routeId} server spans take about 1492 ms, while other route endpoints stay at 1 to 9 ms."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-route-service",
      "to": "ts-travel-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, count(*) n, approx_quantile(duration,0.5)/1e6 p50_ms FROM abnormal_traces WHERE service_name='ts-travel-service' AND attr_span_kind='Client' GROUP BY 1,2,3 ORDER BY 4 DESC",
          "claim": "Travel-service client calls to route-service take about 1492 ms, and its own work stays about 11 ms."
        }
      ]
    },
    {
      "from": "ts-route-service",
      "to": "ts-travel2-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, count(*) n, approx_quantile(duration,0.5)/1e6 p50_ms FROM abnormal_traces WHERE service_name='ts-travel2-service' AND span_name LIKE 'GET%' GROUP BY 1,2,3",
          "claim": "Travel2-service GET admin_trip server spans rise to about 7484 ms, following the route-service delay."
        }
      ]
    },
    {
      "from": "ts-travel-service",
      "to": "ts-admin-travel-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, count(*) n, approx_quantile(duration,0.5)/1e6 p50_ms FROM abnormal_traces WHERE service_name='ts-admin-travel-service' AND attr_span_kind='Client' GROUP BY 1,2,3",
          "claim": "Admin-travel client GET calls to travel services take about 7480 ms, up from about 30 ms."
        }
      ]
    },
    {
      "from": "ts-admin-travel-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, count(*) n, approx_quantile(duration,0.95)/1e6 p95_ms FROM abnormal_traces WHERE service_name='ts-admin-travel-service' AND attr_span_kind='Server' GROUP BY 1,2,3",
          "claim": "Admin-travel getAllTravels server spans reach about 14,970 ms p95, which is what the dashboard waits on."
        }
      ]
    }
  ]
}
```

